ga2v(){return"\u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0629"},
ga3d(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0645\u062c\u0645\u0648\u0639\u0627\u062a \u0628\u0639\u062f."},
ga37(){return"\u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u0623\u0633\u0639\u0627\u0631"},
ga36(){return'\u0639\u0644\u0627\u0645\u0627\u062a \u0627\u062e\u062a\u064a\u0627\u0631\u064a\u0629 \u0645\u062b\u0644 "\u0639\u0627\u062f\u064a"/"\u0645\u0645\u064a\u0632" \u064a\u0645\u0643\u0646 \u0623\u0646 \u062a\u062d\u0645\u0644\u0647\u0627 \u0627\u0644\u0645\u0627\u062f\u0629 \u2014 \u0635\u0646\u0651\u0641 \u0645\u0627\u062f\u062a\u064a\u0646 \u0623\u0648 \u0623\u0643\u062b\u0631 \u0644\u0646\u0641\u0633 \u0646\u0648\u0639 \u0627\u0644\u062d\u0627\u0644\u0629 \u0628\u0634\u0643\u0644 \u0645\u062e\u062a\u0644\u0641 \u0644\u062a\u0642\u062f\u064a\u0645 \u0642\u0627\u0626\u0645\u0629 \u0623\u0633\u0639\u0627\u0631 \u062b\u0627\u0646\u064a\u0629 \u062f\u0648\u0646 \u062a\u0643\u0631\u0627\u0631 \u0646\u0648\u0639 \u0627\u0644\u062d\u0627\u0644\u0629 \u0646\u0641\u0633\u0647.'},
