gV4(){return"\u0627\u0644\u0641\u0627\u062a\u0648\u0631\u0629 \u0628\u0627\u0644\u062f\u0648\u0644\u0627\u0631 \u062a\u0628\u0642\u0649 \u062f\u064a\u0646\u0627\u064b \u0628\u0627\u0644\u062f\u0648\u0644\u0627\u0631. \u0639\u0646\u062f \u062f\u0641\u0639\u0647\u0627 \u0628\u0627\u0644\u062f\u064a\u0646\u0627\u0631 \u064a\u064f\u062d\u0633\u0628 \u0627\u0644\u0645\u0628\u0644\u063a \u0639\u0644\u0649 \u0633\u0639\u0631 \u064a\u0648\u0645 \u0627\u0644\u062f\u0641\u0639."},
gSM(){return"\u0642\u0648\u0627\u0626\u0645 \u0627\u0644\u0637\u0644\u0628\u0627\u062a"},
gEQ(){return"\u0642\u0648\u0627\u0626\u0645 \u0627\u0644\u0637\u0644\u0628\u0627\u062a"},
gSP(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0642\u0648\u0627\u0626\u0645 \u0637\u0644\u0628\u0627\u062a \u0628\u0639\u062f."},
gEO(){return"\u0642\u0627\u0626\u0645\u0629 \u062c\u062f\u064a\u062f\u0629"},
gSU(){return"\u0627\u0633\u0645 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gSQ(){return"\u062a\u0645 \u0627\u0644\u0637\u0644\u0628"},
gSS(){return"\u062a\u062d\u062f\u064a\u062f \u0643\u0645\u0646\u062c\u0632"},
