gQn(){return"\u0632\u0645\u0627\u0646\u06cc \u067e\u0633\u0648\u0648\u0644\u06d5\u06cc \u067e\u0632\u06cc\u0634\u06a9"},
gQo(){return'\u062a\u06d5\u0646\u0647\u0627 \u06a9\u0627\u0631\u06cc\u06af\u06d5\u0631\u06cc \u0644\u06d5\u0633\u06d5\u0631 \u067e\u0633\u0648\u0648\u0644\u06d5\u06cc \u067e\u0632\u06cc\u0634\u06a9\u06cc \u0686\u0627\u067e\u06a9\u0631\u0627\u0648 \u0647\u06d5\u06cc\u06d5. \u0647\u06d5\u06b5\u0628\u0698\u0627\u0631\u062f\u0646\u06cc \u0639\u06d5\u0631\u06d5\u0628\u06cc \u06cc\u0627\u0646 \u06a9\u0648\u0631\u062f\u06cc \u0647\u06d5\u0645\u0648\u0648 \u0628\u06d5\u06b5\u06af\u06d5\u0646\u0627\u0645\u06d5\u06a9\u06d5 \u062f\u06d5\u06a9\u0627\u062a\u06d5 \u0644\u06d5 \u0695\u0627\u0633\u062a\u06d5\u0648\u06d5 \u0628\u06c6 \u0686\u06d5\u067e \u0648 \u062f\u0648\u0627\u06cc \u0646\u0627\u0648\u06cc \u067e\u0632\u06cc\u0634\u06a9\u06d5\u06a9\u06d5 "\u0627\u0644\u0645\u062d\u062a\u0631\u0645" \u0632\u06cc\u0627\u062f \u062f\u06d5\u06a9\u0627\u062a.'},
gRa(){return"\u067e\u06cc\u0634\u0627\u0646\u062f\u0627\u0646\u06cc \u0695\u0627\u067e\u06c6\u0631\u062a \u0628\u06d5 \u062f\u06c6\u0644\u0627\u0631"},
Rb(a){return"\u06a9\u0627\u062a\u06ce\u06a9 \u0646\u0627\u0686\u0627\u0644\u0627\u06a9 \u0628\u06ce\u062a\u060c \u0628\u06d5 "+a+" \u067e\u06cc\u0634\u0627\u0646 \u062f\u06d5\u062f\u0631\u06ce\u062a. \u06a9\u06d5\u06cc\u0633\u06d5 \u0626\u06ce\u0633\u062a\u0627\u06a9\u0627\u0646 \u0644\u06d5 \u0647\u06d5\u0631\u062f\u0648\u0648 \u062d\u0627\u06b5\u06d5\u062a\u062f\u0627 \u0646\u0631\u062e\u06cc \u06af\u06c6\u0695\u06cc\u0646\u06d5\u0648\u06d5\u06cc \u062a\u0627\u06cc\u0628\u06d5\u062a \u0628\u06d5\u062e\u06c6\u06cc\u0627\u0646 \u062f\u06d5\u067e\u0627\u0631\u06ce\u0632\u0646."},
gPw(){return"\u067e\u06c6\u0631\u062a\u0627\u06b5\u06cc \u06a9\u0644\u06cc\u0646\u06cc\u06a9 \u0686\u0627\u0644\u0627\u06a9\u06d5"},
gPx(){return"\u0626\u06d5\u0645\u06d5 \u0646\u0627\u0686\u0627\u0644\u0627\u06a9 \u0628\u06a9\u06d5 \u0626\u06d5\u06af\u06d5\u0631 \u0626\u06d5\u0645 \u062a\u0627\u0642\u06cc\u06af\u06d5\u06cc\u06d5 \u0626\u06d5\u067e\u06cc \u062c\u06cc\u0627\u06a9\u0631\u0627\u0648\u06d5\u06cc \u067e\u06c6\u0631\u062a\u0627\u06b5\u06cc \u067e\u0632\u06cc\u0634\u06a9/\u06a9\u0644\u06cc\u0646\u06cc\u06a9 \u0628\u06d5\u06a9\u0627\u0631\u0646\u0627\u0647\u06ce\u0646\u06ce\u062a \u2014 \u0632\u06d5\u0646\u06af\u06cc \u0626\u0627\u06af\u0627\u062f\u0627\u0631\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5 \u0648 \u0646\u0627\u0645\u06d5\u06a9\u0627\u0646 \u062f\u06d5\u0634\u0627\u0631\u06ce\u062a\u06d5\u0648\u06d5."},
gRn(){return"\u0644\u06cc\u0633\u062a\u06a9\u0631\u0627\u0648\u06d5 \u0628\u06c6 \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc\u06cc \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06d5\u06a9\u0627\u0646"},
gRo(){return"\u06a9\u0627\u062a\u06ce\u06a9 \u06a9\u0648\u0698\u0627\u0648\u06d5\u062a\u06d5\u0648\u06d5\u060c \u0626\u06d5\u0645 \u062a\u0627\u0642\u06cc\u06af\u06d5\u06cc\u06d5 \u062f\u06d5\u0631\u0646\u0627\u06a9\u06d5\u0648\u06ce\u062a \u06a9\u0627\u062a\u06ce\u06a9 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06ce\u06a9 \u0628\u06d5\u062f\u0648\u0627\u06cc \u062a\u0627\u0642\u06cc\u06af\u06d5\u06cc\u06d5\u06a9\u062f\u0627 \u062f\u06d5\u06af\u06d5\u0695\u06ce\u062a \u0628\u06c6 \u067e\u06d5\u06cc\u0648\u06d5\u0633\u062a\u0628\u0648\u0648\u0646\u060c \u0648\u06d5 \u0647\u06cc\u0686 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u062f\u0646\u06cc \u062e\u06c6\u06a9\u0627\u0631\u0627\u0646\u06d5\u06cc \u0646\u0648\u06ce\u06cc \u067e\u0632\u06cc\u0634\u06a9/\u06a9\u0644\u06cc\u0646\u06cc\u06a9 \u0648\u06d5\u0631\u0646\u0627\u06af\u0631\u06ce\u062a."},
gQ8(){return"\u0634\u0627\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u06a9\u06d5\u06cc\u0633\u06d5 \u0647\u06d5\u06b5\u0648\u06d5\u0634\u06ce\u0646\u0631\u0627\u0648\u06d5\u06a9\u0627\u0646 \u0644\u06d5 \u062a\u06d5\u062e\u062a\u06d5\u06cc \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646"},
gQ9(){return"\u06a9\u0627\u062a\u06ce\u06a9 \u06a9\u0627\u0631\u0627 \u0628\u06ce\u062a\u060c \u06a9\u06d5\u06cc\u0633\u06cc \u0647\u06d5\u06b5\u0648\u06d5\u0634\u06ce\u0646\u0631\u0627\u0648 \u0628\u06d5 \u062a\u06d5\u0648\u0627\u0648\u06cc \u0644\u06d5 \u062a\u06d5\u062e\u062a\u06d5\u06cc \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646 \u062f\u06d5\u0631\u0646\u0627\u06a9\u06d5\u0648\u06ce\u062a\u060c \u0644\u06d5 \u062c\u06cc\u0627\u062a\u06cc \u0626\u06d5\u0648\u06d5\u06cc \u06a9\u0627\u06b5 \u062f\u06cc\u0627\u0631 \u0628\u06ce\u062a \u0644\u06d5 \u0633\u062a\u0648\u0648\u0646\u06cc \u0642\u06c6\u0646\u0627\u063a\u06d5\u06a9\u06d5\u06cc. \u0647\u06d5\u0631\u0648\u06d5\u0647\u0627 \u0628\u06d5 \u062a\u06d5\u0648\u0627\u0648\u06cc \u062f\u06d5\u062a\u0648\u0627\u0646\u0631\u06ce\u062a \u0628\u06af\u06d5\u0695\u062f\u0631\u06ce\u062a \u0628\u06c6\u06cc \u0644\u06d5 \u0647\u06d5\u0645\u0648\u0648 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646."},
gQi(){return"\u0698\u0645\u0627\u0631\u06d5\u06cc\u06d5\u06a9\u06cc \u062f\u0631\u0648\u0633\u062a\u06cc \u0695\u06c6\u0698 \u0628\u0646\u0648\u0648\u0633\u06d5 (\u0632\u06cc\u0627\u062a\u0631 \u0644\u06d5 0)."},
