gPe(){return"\u062c\u06c6\u0631\u06d5\u06a9\u0627\u0646\u06cc \u0647\u0627\u0648\u067e\u06ce\u0686"},
gPf(){return"\u06a9\u06c6\u0646\u062a\u0631\u06c6\u06b5\u06cc \u0626\u06d5\u0648\u06d5 \u062f\u06d5\u06a9\u0627\u062a \u06a9\u06d5 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u0627\u0646\u060c \u0648 \u067e\u0632\u06cc\u0634\u06a9\u06d5\u06a9\u0627\u0646 \u06a9\u0627\u062a\u06ce\u06a9 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9 \u062f\u06d5\u0646\u06ce\u0631\u0646\u060c \u0695\u06ce\u06af\u06d5\u06cc\u0627\u0646 \u067e\u06ce\u062f\u0631\u0627\u0648\u06d5 \u0686\u06cc \u0647\u0627\u0648\u067e\u06ce\u0686\u06cc \u06a9\u06d5\u06cc\u0633\u06ce\u06a9 \u0628\u06a9\u06d5\u0646."},
