gTc(){return"\u0644\u06ce\u06af\u06d5\u0631\u06cc\u0627\u0646 \u0644 \u06a9\u0627\u0644\u0627\u06cc\u0627\u0646"},
gT1(){return"\u0632\u06ce\u062f\u06d5\u06a9\u0631\u0646 \u0648\u06d5\u06a9 \u06a9\u0627\u0644\u0627\u06cc\u06d5\u06a9\u0627 \u0646\u0648\u06cc"},
