gSY(){return"\u0631\u06d5\u0646\u06af \u0648 \u0642\u06d5\u0628\u0627\u0631\u06ce\u0646 \u0647\u06d5\u0645\u0627\u0646 \u0645\u0627\u062f\u062f\u06ce \u0644 \u0628\u0646 \u0626\u06ce\u06a9 \u06a9\u0627\u0644\u0627\u06cc\u0627 \u0633\u06d5\u0631\u06d5\u06a9\u06cc \u062f\u0627\u0628\u0646\u06ce"},
gSG(){return"\u0626\u06d5\u06a4\u06ce \u06a9\u0627\u0644\u0627\u06cc\u06ce \u0631\u06d5\u0646\u06af/\u0642\u06d5\u0628\u0627\u0631\u06ce\u0646 \u062e\u06c6 \u0647\u06d5\u0646\u06d5\u060c \u0644\u06d5\u0648\u0645\u0627 \u0648\u06d5\u06a9 \u0645\u0627\u062f\u062f\u0627 \u0633\u06d5\u0631\u06d5\u06a9\u06cc \u062f\u0645\u06cc\u0646\u06cc\u062a"},
gSE(){return"\u0628\u0627\u0631\u06a9\u06c6\u062f\u06ce \u0642\u0648\u062a\u06cc\u06ce (\u0698\u0645\u0627\u0631\u0627 \u0628\u06d5\u0631\u0647\u06d5\u0645\u06cc)"},
SF(a){return"\u0628\u0627\u0631\u06a9\u06c6\u062f: "+a},
Tm(a){return"\u062c\u06c6\u0631\u06d5\u06a9\u06ce "+a},
gSD(){return"\u0632\u06ce\u062f\u06d5\u06a9\u0631\u0646\u0627 \u0631\u06d5\u0646\u06af / \u0642\u06d5\u0628\u0627\u0631\u06d5"},
EU(a){var s=null
return A.aG(a,s,this.a,s,"1 \u062c\u06c6\u0631",""+a+" \u062c\u06c6\u0631",s,s)},
gadm(){return"\u0633\u06a9\u0627\u0646\u06a9\u0631\u0646\u0627 \u0642\u0648\u062a\u06cc\u06d5\u06a9\u0627 \u0645\u0627\u062f\u062f\u06ce \u0626\u06ce\u06a9 \u0642\u0648\u062a\u06cc\u06ce \u0628 \u0646\u0627\u06a4\u06ce \u062a\u06d5 \u0698 \u06a9\u06c6\u06af\u06d5\u0647\u06ce \u062f\u0628\u06d5\u062a."},
gadn(){return"\u0626\u06d5\u06a4 \u0628\u0627\u0631\u06a9\u06c6\u062f\u06d5 \u0647\u06ce\u0634\u062a\u0627 \u0628 \u0686 \u06a9\u0627\u0644\u0627\u06cc\u06ce\u0646 \u06a9\u06c6\u06af\u06d5\u0647\u06ce \u06a4\u06d5 \u0646\u06d5\u0647\u0627\u062a\u06cc\u06d5 \u06af\u0631\u06ce\u062f\u0627\u0646 \u2014 \u062f\u0627\u062e\u0648\u0627\u0632\u06ce \u0698 \u0626\u06d5\u062f\u0645\u06cc\u0646\u06d5\u06a9\u06cc \u0628\u06a9\u06d5 \u06af\u0631\u06ce \u0628\u062f\u06d5\u062a."},
