gTj(){return"\u0626\u06d5\u06a4 \u0642\u0648\u062a\u06cc\u06d5 \u06a9\u06cc\u0698 \u06a9\u0627\u0644\u0627\u06cc\u06d5\u061f"},
gTi(){return"\u0631\u06d5\u0646\u06af/\u0642\u06d5\u0628\u0627\u0631\u06ce \u062f\u0631\u0648\u0633\u062a \u0647\u06d5\u0644\u0628\u0698\u06ce\u0631\u06d5. \u0698 \u0646\u0648\u06a9\u06d5 \u0626\u06d5\u067e \u062f\u06ce \u06a4\u06ce \u0698 \u06cc\u06ce\u0646 \u062f\u06cc \u062c\u0648\u062f\u0627 \u06a9\u06d5\u062a."},
gaba(){return"\u0633\u06a9\u0627\u0646\u06d5\u0631"},
