gagc(){return"\u0633\u06a9\u0627\u0646\u06d5\u0631\u06ce \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u06ce \u0647\u06d5\u0644\u0628\u0698\u06ce\u0631\u06d5 (\u06cc\u0627\u0646 \xab\u062f\u06d5\u0631\u06d5\u06a9\u06cc\xbb)."},
gRc(){return"\u06a9\u06d5\u06cc\u0633\u06ce \u0646\u0648\u06cc: \u062c\u06c6\u0631\u060c \u0631\u06d5\u0646\u06af \u0648 \u062f\u062f\u0627\u0646 \u067e\u06ce\u062f\u06a4\u06cc\u0646\u06d5"},
gRd(){return"\u0686 \u062a\u0634\u062a \u0628\u06d5\u0631\u06cc \u0646\u0648\u06a9\u06d5 \u0646\u06d5\u0647\u0627\u062a\u06cc\u06d5 \u0647\u06d5\u0644\u0628\u0698\u0627\u0631\u062a\u0646: \u062f\u06a4\u06ce\u062a \u062c\u06c6\u0631\u06ce \u06a9\u06d5\u06cc\u0633\u06cc \u0628\u0647\u06ce\u062a\u06d5 \u0647\u06d5\u0644\u0628\u0698\u0627\u0631\u062a\u0646\u060c \u062f\u062f\u0627\u0646 (\u06cc\u0627\u0646 \u0641\u06d5\u06a9) \u0628\u0647\u06ce\u0646\u06d5 \u062f\u06cc\u0627\u0631\u06a9\u0631\u0646\u060c \u0648 \u0631\u06d5\u0646\u06af\u06d5\u06a9 \u06cc\u0627\u0646 \xab\u067e\u0627\u0634\u0627\u0646 \u0628\u0695\u06cc\u0627\u0631 \u0628\u062f\u06d5\xbb \u0644 \u0647\u06d5\u0631 \u062c\u0647\u06d5\u06a9\u06ce \u062c\u06c6\u0631 \u0631\u06d5\u0646\u06af\u06cc \u0628\u06a9\u0627\u0631\u0628\u06cc\u0646\u06cc\u062a \u0628\u0647\u06ce\u062a\u06d5 \u0647\u06d5\u0644\u0628\u0698\u0627\u0631\u062a\u0646. \u062f\u06a9\u062a\u06c6\u0631 \u062a\u0646\u06ce \u0628 \u062e\u06c6 \u062f\u0647\u06ce\u062a\u06d5 \u067e\u0695\u06a9\u0631\u0646 \u062f\u06d5\u0645\u06ce \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06ce \u062a\u0646\u06ce \u0626\u06ce\u06a9 \u062f\u06a9\u062a\u06c6\u0631 \u0647\u06d5\u0628\u06cc\u062a."},
gQa(){return"\u06a9\u06d5\u06cc\u0633\u06ce \u0646\u0648\u06cc: \u06a4\u06d5\u0634\u0627\u0631\u062a\u0646\u0627 \u062a\u06ce\u0686\u0648\u0648\u0646 \u0648 \u0628\u0647\u0627\u06cc\u06ce \u062f\u06c6\u0644\u0627\u0631\u06cc"},
gQb(){return"\u0628\u06c6 \u0648\u0627\u0646 \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u06ce\u0646 \u0628\u06d5\u062f\u0648\u06cc\u062f\u0627\u0686\u0648\u0648\u0646\u0627 \u062a\u06ce\u0686\u0648\u0648\u0646\u0627 \u0647\u06d5\u0631 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u06cc \u06cc\u0627\u0646 \u0628\u0647\u0627\u06cc\u06ce \u0628 \u062f\u06c6\u0644\u0627\u0631\u06cc \u0646\u0627\u06a9\u06d5\u0646. \u062a\u06ce\u0686\u0648\u0648\u0646\u0627 \u06a9\u06d5\u062a\u06d5\u0644\u06c6\u06af\u06cc \u0648 \u0628\u0647\u0627\u06cc\u06ce \u0646\u0648\u06a9\u06d5 \u06cc\u06ce \u062f\u06c6\u0644\u0627\u0631\u06cc \u06cc\u06ce \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u06ce \u0647\u06ce\u0634\u062a\u0627 \u062f\u0647\u06ce\u0646\u06d5 \u067e\u0627\u0634\u06d5\u06a9\u06d5\u0641\u062a\u06a9\u0631\u0646\u060c \u0644\u06d5\u0648\u0645\u0627 \u0631\u0627\u067e\u06c6\u0631\u062a \u062a\u06ce\u06a9 \u0646\u0627\u0686\u0646. \u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u0627 \u06a9\u06d5\u06cc\u0633\u06cc \u0647\u06ce\u0634\u062a\u0627 \u0647\u06d5\u0631 \u062f\u0648\u0648\u0627\u0646 \u067e\u06cc\u0634\u0627\u0646 \u062f\u062f\u06d5\u062a."},
gPa(){return"\u0633\u06a9\u0627\u0646\u0627 QR \u0698 \u0648\u06ce\u0646\u06d5\u06cc\u0627\u0646"},
gPb(){return"\u062a\u06d5\u062e\u062a \u2190 \u0633\u06a9\u0627\u0646\u0627 QR \u062f\u0648\u06af\u0645\u06d5\u06cc\u0627 \xab\u0698 \u0648\u06ce\u0646\u06d5\u06cc\u0627\u0646\xbb \u067e\u06cc\u0634\u0627\u0646 \u062f\u062f\u06d5\u062a: \u0648\u06ce\u0646\u06d5\u06cc\u06ce\u0646 \u0644\u06ce\u0628\u0644\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u0627\u0646 \u0698 \u06af\u0627\u0644\u06d5\u0631\u06cc\u06ce \u0647\u06d5\u0644\u0628\u0698\u06ce\u0631\u06d5\u060c \u067e\u06ce\u062f\u0627 \u0628\u0686\u06d5\u060c \u0648 \u0628 \u0626\u06ce\u06a9 \u06a9\u0644\u06cc\u06a9\u06ce \u067e\u06ce\u0634\u06a4\u06d5 \u0628\u0628\u06d5. \u0648\u06ce\u0646\u06d5\u06cc\u06d5\u06a9 \u0646\u0627\u0633\u06d5\u0644\u0645\u06cc\u0646\u06cc\u062a \u06a9\u0648 \u06a9\u0627\u0631 \u0644 \u0648\u06ce \u0633\u062a\u06d5\u06cc\u0634\u0646\u06ce \u0628\u0648\u0648\u060c \u0644\u06d5\u0648\u0645\u0627 \u06a4\u06d5\u0645\u0631\u0627\u06cc \u062f\u0645\u06cc\u0646\u06cc\u062a \u0647\u06d5\u062a\u0627 \u062a\u0648 \u0647\u06d5\u0644\u062f\u06a9\u06d5\u06cc."},
gRg(){return"\u062f\u0627\u062e\u0648\u0627\u0632\u06a9\u0631\u0646\u0627 \u067e\u06d5\u06cc\u06a4\u0627 \u0646\u0647\u06ce\u0646\u06cc \u0628\u06d5\u0631\u06cc \u0698\u06ce\u0628\u0631\u0646\u0627 \u0628\u0695\u0627\u0646"},
gRh(){return"\u0698\u06ce\u0628\u0631\u0646\u0627 \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u06d5\u06a9\u06ce\u060c \u062e\u06d5\u0631\u062c\u06cc\u06d5\u06a9\u06ce\u060c \u0645\u0648\u0648\u0686\u06d5\u06cc\u06d5\u06a9\u06ce\u060c \u067e\u0633\u0648\u0648\u0644\u06d5 \u06cc\u0627\u0646 \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u0627 \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u06cc\u060c \u06cc\u0627\u0646 \u0644\u06a4\u06cc\u0646\u06d5\u06a9\u0627 \u0642\u0627\u0633\u06ce\u060c \u0628\u06d5\u0631\u06cc \u0647\u06d5\u0645\u06cc\u06ce \u062f\u0627\u062e\u0648\u0627\u0632\u0627 \u067e\u06d5\u06cc\u06a4\u0627 \u0646\u0647\u06ce\u0646\u06cc \u062f\u06a9\u06d5\u062a."},
gLi(){return"\u06a9\u06c6"},
gLg(){return"\u0644 \u062f\u0648\u06cc\u06a4 \u0628\u0695\u06ce"},
