gST(){return"\u06a4\u06d5\u06a9\u0631\u0646\u06d5\u06a4\u06d5"},
gSO(){return"\u06a4\u06cc \u0644\u06cc\u0633\u062a\u06ce \u0698\u06ce\u0628\u0628\u06d5\u061f"},
gSN(){return"\u0626\u06d5\u06a4\u06d5 \u0644\u06cc\u0633\u062a\u06ce \u0648 \u0647\u06d5\u0645\u06cc \u062a\u0634\u062a\u06ce\u0646 \u062a\u06ce\u062f\u0627 \u0698\u06ce\u062f\u0628\u06d5. \u0646\u0627\u0634\u06ce\u062a \u067e\u0627\u0634\u06af\u06d5\u0632 \u0628\u06cc\u062a\u06d5\u06a4\u06d5."},
